SourceCode.Declaration:
/// <summary>
/// Abstract class for posting MET Customer MDF Consolidation records
/// </summary>
public abstract class METCustomerMDFPosting
{
    CustAccount custAccount;

}

Method.Source:
/// <summary>
/// Abstract method to get the query for fetching METCustomerMDFConsolidationTable records
/// </summary>
/// <returns>Query</returns>
abstract Query getQuery()
{

}

/// <summary>
/// Parameter method for customer account
/// </summary>
/// <param name = "_custAccount">CustAccount</param>
/// <returns>CustAccount</returns>
public CustAccount parmCustAccount(CustAccount _custAccount = custAccount)
{
    custAccount = _custAccount;

    return custAccount;
}

/// <summary>
/// Update the query to filter by customer account
/// </summary>
/// <param name = "_query">CustAccount</param>
/// <returns>CustAccount</returns>
Query updateQuery(Query _query)
{
    _query.dataSourceTable(tableNum(METCustomerMDFConsolidationTable)).addRange(fieldNum(METCustomerMDFConsolidationTable, CustAccount)).value(custAccount);

    return _query;
}

/// <summary>
/// Process the posting of consolidation records
/// </summary>
void process()
{
    #OCCRetryCount

    try
    {
        ttsbegin;

        Query query = this.getQuery();
        query = this.updateQuery(query);

        QueryRun queryRun = new QueryRun(query);

        while(queryRun.next())
        {
            METCustomerMDFConsolidationTable consolidationPosting = queryRun.get(tableNum(METCustomerMDFConsolidationTable));

            this.processConsolidationPosting(consolidationPosting);
        }

        if(this.autoPost())
        {
            this.post();
        }

        ttscommit;

    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= #RetryNum)
        {
            throw Exception::Deadlock;
        }
        else
        {
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch (Exception::Error)
    {
        // catch the errors so processing can continue
        curext(); // avoids a warning about an empty block
    }
}

/// <summary>
/// Process a single consolidation posting
/// </summary>
/// <param name = "_consolidationPosting">METCustomerMDFConsolidationTable</param>
void processConsolidationPosting(METCustomerMDFConsolidationTable _consolidationPosting)
{
    RecId postingRefRecId = this.createConsolidationPostingLine(_consolidationPosting);

    this.updateCustomerMDFConsolidationTable(_consolidationPosting, postingRefRecId);
}

/// <summary>
/// Abstract method to update the METCustomerMDFConsolidationTable with the posting reference
/// </summary>
/// <param name = "_consolidationPosting">METCustomerMDFConsolidationTable</param>
/// <param name = "_postingRefRecId">RefRecId</param>
abstract void updateCustomerMDFConsolidationTable(METCustomerMDFConsolidationTable _consolidationPosting, RefRecId _postingRefRecId)
{
}

/// <summary>
/// Abstract method to determine if posting should be done automatically
/// </summary>
/// <returns>boolean</returns>
abstract boolean autoPost()
{
}

/// <summary>
/// Abstract method to post the created records
/// </summary>
abstract void post()
{
}

/// <summary>
/// Abstract method to create a posting line for the consolidation record
/// </summary>
/// <param name = "_consolidationTable">METCustomerMDFConsolidationTable</param>
/// <returns>RefRecId</returns>
abstract RefRecId createConsolidationPostingLine(METCustomerMDFConsolidationTable _consolidationTable)
{
}

/// <summary>
/// Abstract method to get the table ID for the posting records
/// </summary>
/// <returns>RefTableId</returns>
abstract RefTableId getPostingTableId()
{
}
